function overpassQuery(c){const b=bbox(c).map(x=>x.toFixed(6)).join(',');return `[out:json][timeout:75];(way["highway"]["highway"!~"motorway|motorway_link|trunk|trunk_link|construction|proposed|raceway|bus_guideway|platform"](${b});node["amenity"](${b});node["tourism"](${b});node["shop"](${b});node["leisure"="park"](${b}););out body;>;out skel qt;`}
async function fetchOverpass(q){const urls=['https://overpass.kumi.systems/api/interpreter','https://overpass-api.de/api/interpreter','https://overpass.private.coffee/api/interpreter'];let errs=[];for(const url of urls){try{const ctrl=new AbortController(),timeout=setTimeout(()=>ctrl.abort(),85000);let res;try{res=await fetch(url,{method:'POST',body:new URLSearchParams({data:q}),signal:ctrl.signal});}finally{clearTimeout(timeout)}if(!res.ok)throw Error('HTTP '+res.status);const obj=await res.json();if(!Array.isArray(obj.elements))throw Error('Неверный ответ API');return obj;}catch(e){errs.push(new URL(url).hostname+': '+e.message)}}throw Error('Публичные серверы недоступны: '+errs.join('; '))}
$('analyze').onclick=async()=>{clearResults();$('analyze').disabled=true;state('Загружаю улицы и объекты из OpenStreetMap. Это может занять время…');try{const c=[...center],data=await fetchOverpass(overpassQuery(c));data._center=c;raw=data;if(haversine(c,center)>2){state('Точка изменилась во время загрузки: повтори расчёт.');return}calculate(data)}catch(e){state('Не удалось загрузить данные: '+e.message+'. Попробуй снова или импортируй сохранённый JSON.',true)}finally{$('analyze').disabled=false}}
function walkable(t){const h=t.highway;if(!h)return false;if(t.access==='private'||t.access==='no'||t.foot==='private'||t.foot==='no')return false;if(['motorway','motorway_link','trunk','trunk_link','construction','proposed','raceway','bus_guideway','platform'].includes(h))return false;if(['cycleway','bridleway'].includes(h)&&t.foot!=='yes'&&t.foot!=='designated')return false;if(t.sidewalk==='no'&&['primary','secondary','tertiary'].includes(h)&&t.foot!=='yes')return false;return true}
class Heap{constructor(){this.a=[]}push(x){let a=this.a;a.push(x);let i=a.length-1;while(i>0){let p=(i-1)>>1;if(a[p][0]<=x[0])break;a[i]=a[p];i=p}a[i]=x}pop(){let a=this.a,top=a[0],x=a.pop();if(a.length){let i=0;while(2*i+1<a.length){let j=i*2+1;if(j+1<a.length&&a[j+1][0]<a[j][0])j++;if(a[j][0]>=x[0])break;a[i]=a[j];i=j}a[i]=x}return top}get length(){return this.a.length}}
function build(data){const nodes=new Map(),ways=[],pois=[];for(const e of data.elements){if(e.type==='node'&&typeof e.lat==='number'){nodes.set(e.id,[e.lat,e.lon]);if(e.tags&&classify(e.tags))pois.push({id:`node/${e.id}`,coord:[e.lat,e.lon],category:classify(e.tags),name:e.tags.name||e.tags['name:en']||'Без названия',tags:e.tags});}else if(e.type==='way'&&e.tags&&walkable(e.tags))ways.push(e)}const adj=new Map(),edges=[];function connect(a,b,d){if(!adj.has(a))adj.set(a,[]);adj.get(a).push([b,d])}for(const w of ways){for(let i=1;i<w.nodes.length;i++){const a=w.nodes[i-1],b=w.nodes[i],ca=nodes.get(a),cb=nodes.get(b);if(!ca||!cb)continue;const d=haversine(ca,cb);if(d<0.01||d>1000)continue;connect(a,b,d);connect(b,a,d);edges.push([a,b,d])}}return {nodes,adj,edges,pois,ways}}
function classify(t){if(t.amenity)return t.amenity;if(t.tourism)return t.tourism;if(t.shop)return 'shop';if(t.leisure==='park')return 'park';return null}
function closest(nodes,c){let best=null,bestD=Infinity;for(const [id,p] of nodes){const d=haversine(p,c);if(d<bestD){bestD=d;best=id}}return {id:best,d:bestD}}
function dijkstra(adj,source,max){const d=new Map([[source,0]]),heap=new Heap();heap.push([0,source]);while(heap.length){const [v,u]=heap.pop();if(v!==d.get(u))continue;if(v>max)break;for(const [to,w] of adj.get(u)||[]){const nd=v+w;if(nd<=max&&nd<(d.get(to)??Infinity)){d.set(to,nd);heap.push([nd,to])}}}return d}
function interp(a,b,f){return [a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f]}
function roadFeatures(g,dist,max){let length=0;const features=[];for(const [a,b,w] of g.edges){const da=dist.get(a)??Infinity,db=dist.get(b)??Infinity;if(da>max&&db>max)continue;let c1=g.nodes.get(a),c2=g.nodes.get(b),fraction=1;if(da<=max&&db>max){fraction=Math.min(1,(max-da)/w);c2=interp(c1,c2,fraction)}else if(db<=max&&da>max){fraction=Math.min(1,(max-db)/w);c1=interp(c2,c1,fraction)}length+=w*fraction;features.push({type:'Feature',geometry:{type:'LineString',coordinates:[[c1[1],c1[0]],[c2[1],c2[0]]]},properties:{length_m:Math.round(w*fraction)}})}return {features,length}}
function spatialIndex(nodes){const s=new Map(),size=.002;for(const [id,p] of nodes){const k=Math.floor(p[0]/size)+','+Math.floor(p[1]/size);if(!s.has(k))s.set(k,[]);s.get(k).push([id,p])}return {s,size}}
function nearby(index,p){const {s,size}=index,y=Math.floor(p[0]/size),x=Math.floor(p[1]/size);let min=Infinity,id=null;for(let range=0;range<=3;range++){for(let i=-range;i<=range;i++)for(let j=-range;j<=range;j++){if(range>0&&Math.max(Math.abs(i),Math.abs(j))!==range)continue;for(const [k,c] of s.get((y+i)+','+(x+j))||[]){const d=haversine(p,c);if(d<min){min=d;id=k}}}const latitudeMeters=size*111000,longitudeMeters=latitudeMeters*Math.cos(p[0]*Math.PI/180);const lower=Math.min(latitudeMeters,longitudeMeters)*range;if(id!==null&&min<lower)break}return {id,d:min}}
function calculate(data){clearResults();state('Считаю кратчайшие пути по дорожной сети…');try{const g=build(data),start=closest(new Map([...g.adj.keys()].map(k=>[k,g.nodes.get(k)])),center),max=minutes*75;if(start.id===null||start.d>200){state('Рядом с точкой нет пешеходной улицы (менее 200 м). Выбери другое место.',true);return}const networkBudget=Math.max(0,max-start.d),dist=dijkstra(g.adj,start.id,networkBudget),road=roadFeatures(g,dist,networkBudget),index=spatialIndex(new Map([...g.adj.keys()].map(k=>[k,g.nodes.get(k)])));const visible=[];for(const p of g.pois){const nearest=nearby(index,p.coord);if(nearest.d>100)continue;const d=(dist.get(nearest.id)??Infinity)+nearest.d;if(d+start.d<=max)visible.push({...p,distance:Math.round(d+start.d),walkMin:+((d+start.d)/75).toFixed(1)})}const features=[...road.features,...visible.map(p=>({type:'Feature',geometry:{type:'Point',coordinates:[p.coord[1],p.coord[0]]},properties:{name:p.name,category:p.category,walk_min:p.walkMin,distance_m:p.distance,osm_id:p.id}}))];last={road,visible,features,center:[...center],minutes,reachableNodes:dist.size,max,start};roadLayer=L.geoJSON(road.features,{style:{color:'#288761',weight:4,opacity:.82}}).addTo(map);poiLayer=L.layerGroup(visible.map(p=>L.circleMarker(p.coord,{radius:4,weight:1,color:'#fff',fillColor:'#c17c35',fillOpacity:.85}).bindPopup(`<b>${escapeHtml(p.name)}</b><br>${escapeHtml(p.category)} · ≈${p.walkMin} мин`))).addTo(map);$('roadLength').textContent=(road.length/1000).toFixed(1).replace('.',',');$('poiCount').textContent=visible.length.toLocaleString('ru');$('nodesCount').textContent=dist.size.toLocaleString('ru');$('walkDist').textContent=(max/1000).toFixed(2).replace('.',',');$('maptitle').textContent=`${minutes} минут пешком · Гданьск`;$('mapdesc').textContent=`${(road.length/1000).toFixed(1)} км улиц · ${visible.length} объектов · OpenStreetMap`;state(`Готово. Просчитано ${g.edges.length.toLocaleString('ru')} дорожных сегментов; ближайшая вершина в ${Math.round(start.d)} м от точки. Учтены только объекты, внесённые в OpenStreetMap. Зона показана как достижимые уличные участки, не как неточный круг.`);if(road.features.length){const bounds=roadLayer.getBounds();if(bounds.isValid())map.fitBounds(bounds.pad(.2),{maxZoom:15})}}catch(e){state('Ошибка расчёта: '+e.message,true)}}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
