let activeModule='accessibility',extraLayer=null,buildData=null,syntaxData=null,centreData=null,compareData=[];
const moduleNames={development:'Застройка',accessibility:'Доступность',syntax:'Связанность улиц',centre:'Городские центры',compare:'Сравнение городов'};
function extraClear(){if(extraLayer){map.removeLayer(extraLayer);extraLayer=null}}
function switchModule(name){activeModule=name;document.querySelectorAll('#moduleNav button').forEach(b=>b.classList.toggle('selected',b.dataset.module===name));$('accessPanel').hidden=name!=='accessibility';for(const n of ['development','syntax','centre','compare'])$(n+'Panel').hidden=n!==name;extraClear();if(roadLayer)map.removeLayer(roadLayer);if(poiLayer)map.removeLayer(poiLayer);if(name==='accessibility'){if(roadLayer)roadLayer.addTo(map);if(poiLayer)poiLayer.addTo(map)}$('maptitle').textContent=moduleNames[name]+' · Gdańsk';$('mapdesc').textContent='Выбери точку и выполни анализ';}
$('moduleNav').onclick=e=>{const b=e.target.closest('[data-module]');if(b)switchModule(b.dataset.module)};
const metricHtml=(items)=>items.map(([value,label])=>`<div class="metric"><div class="number">${value}</div><div class="mlabel">${label}</div></div>`).join('');
const formNum=id=>Number($(id).value);
function xy(c){return [c[1],c[0]]}
function planarArea(coords){if(coords.length<3)return 0;const latitude=coords.reduce((s,c)=>s+c[1],0)/coords.length, longitude=coords.reduce((s,c)=>s+c[0],0)/coords.length, mx=111320*Math.cos(latitude*Math.PI/180),my=111320;let twice=0;for(let i=0;i<coords.length;i++){const p=coords[i],q=coords[(i+1)%coords.length];twice+=((p[0]-longitude)*mx)*((q[1]-latitude)*my)-((q[0]-longitude)*mx)*((p[1]-latitude)*my)}return Math.abs(twice/2)}
function valueFmt(n){return Math.round(n).toLocaleString('ru')}
function featuresCollection(fs){return {type:'FeatureCollection',features:fs}}
async function buildingLoad(){let r=formNum('buildRadius'),b=bbox(center,r).map(x=>x.toFixed(6)).join(',');const q=`[out:json][timeout:75];way["building"](${b});out geom;`;const data=await fetchOverpass(q);return data.elements.filter(e=>e.type==='way'&&e.geometry?.length>=4)}
$('runBuild').onclick=async()=>{$('runBuild').disabled=true;$('buildStatus').textContent='Загружаю здания из OSM…';extraClear();try{const buildings=await buildingLoad(),r=formNum('buildRadius'),flatArea=formNum('flatArea'),occ=formNum('occupancy');if(!(flatArea>0&&occ>0))throw Error('Проверь ввод площади и жителей');let housing=0,area=0,flats=0,dated=0,residential=0;const fs=[];for(const b of buildings){const t=b.tags||{},ring=b.geometry.map(x=>[x.lon,x.lat]);if(haversine(center,[b.geometry[0].lat,b.geometry[0].lon])>r)continue;const sq=planarArea(ring),levels=Number(t['building:levels'])||3;const residentialTag=['apartments','residential','house','detached','terrace','semidetached_house','dormitory'].includes(t.building);const units=Number(t['building:flats'])||((residentialTag)?Math.max(1,Math.round(sq*levels*.75/flatArea)):0);if(residentialTag){housing++;flats+=units;residential++}area+=sq;if(t['start_date']||t['building:year']||t['construction_date'])dated++;fs.push({type:'Feature',geometry:{type:'Polygon',coordinates:[ring]},properties:{osm_id:b.id,building:t.building,area_m2:Math.round(sq),levels,flats_estimate:units,residential:residentialTag,year:t.start_date||t['building:year']||null}})}buildData=fs;extraLayer=L.geoJSON(featuresCollection(fs),{style:f=>({color:'#fff',weight:.55,fillColor:f.properties.residential?'#cb7653':'#7c8a83',fillOpacity:.70})}).addTo(map);$('buildMetrics').innerHTML=metricHtml([[valueFmt(fs.length),'зданий в выборке'],[valueFmt(residential),'жилых зданий с тегом'],[valueFmt(flats),'оценка квартир'],[valueFmt(flats*occ),'оценка жителей']]);$('buildStatus').textContent=`Готово. Площадь контуров ≈ ${valueFmt(area)} м². Год постройки указан для ${dated} зданий. Оценки квартир/жителей не относятся исключительно к новостройкам.`;if(fs.length)map.fitBounds(extraLayer.getBounds().pad(.1),{maxZoom:15})}catch(e){$('buildStatus').textContent='Ошибка: '+e.message}finally{$('runBuild').disabled=false}};
$('buildExport').onclick=()=>{if(!buildData){$('buildStatus').textContent='Сначала рассчитай застройку.';return}download('buildings-gdansk.geojson',JSON.stringify(featuresCollection(buildData)),'application/geo+json')};
async function ensureLocalRaw(){if(raw&&raw._center&&haversine(raw._center,center)<5)return raw;const data=await fetchOverpass(overpassQuery(center));data._center=[...center];raw=data;return data}
$('runSyntax').onclick=async()=>{$('runSyntax').disabled=true;$('syntaxStatus').textContent='Считываю уличную сеть и считаю количество соединений…';extraClear();try{const g=build(await ensureLocalRaw()),degrees=new Map();for(const [n,list] of g.adj)degrees.set(n,new Set(list.map(e=>e[0])).size);let intersections=[...degrees.values()].filter(v=>v>=3).length,fs=[];for(const [a,b,d] of g.edges){const k=((degrees.get(a)||0)+(degrees.get(b)||0))/2;fs.push({type:'Feature',geometry:{type:'LineString',coordinates:[xy(g.nodes.get(a)),xy(g.nodes.get(b))]},properties:{length_m:d,mean_degree:k}})}syntaxData=fs;extraLayer=L.geoJSON(featuresCollection(fs),{style:f=>({color:f.properties.mean_degree>=3.5?'#d85f41':f.properties.mean_degree>=2.5?'#e8aa50':'#407f76',weight:2.5,opacity:.82})}).addTo(map);$('syntaxMetrics').innerHTML=metricHtml([[valueFmt(g.edges.length),'сегментов сети'],[valueFmt(intersections),'пересечений (степень ≥ 3)'],[valueFmt(g.adj.size),'узлов сети'],[( [...degrees.values()].reduce((a,b)=>a+b,0)/Math.max(1,degrees.size)).toFixed(2),'средняя степень узла']]);$('syntaxStatus').textContent='Рассчитана топологическая связность. Для полной Space Syntax понадобится отдельная сегментная/angular-модель.'}catch(e){$('syntaxStatus').textContent='Ошибка: '+e.message}finally{$('runSyntax').disabled=false}};
$('syntaxExport').onclick=()=>{if(syntaxData)download('street-connectivity.geojson',JSON.stringify(featuresCollection(syntaxData)),'application/geo+json');else $('syntaxStatus').textContent='Сначала рассчитай сеть.'};
function poiCategory(tags){if(tags.tourism==='museum'||tags.tourism==='attraction'||tags.historic)return 'Культура / туризм';if(['restaurant','cafe','bar','pub','fast_food'].includes(tags.amenity))return 'Еда / напитки';if(tags.shop)return 'Торговля';if(['school','university','library','hospital','clinic'].includes(tags.amenity))return 'Социальные объекты';return 'Другие услуги'}
$('runCentre').onclick=async()=>{$('runCentre').disabled=true;$('centreStatus').textContent='Загружаю городские объекты…';extraClear();try{const d=await ensureLocalRaw(),points=d.elements.filter(e=>e.type==='node'&&e.tags&&classify(e.tags)&&typeof e.lat==='number');const cells=new Map(),group=new Map(),features=[];let valid=0;for(const p of points){const c=[p.lat,p.lon];if(haversine(center,c)>2000)continue;valid++;const cat=poiCategory(p.tags),k=Math.floor((p.lat-center[0])*111320/250)+','+Math.floor((p.lon-center[1])*111320*Math.cos(center[0]*Math.PI/180)/250);cells.set(k,(cells.get(k)||0)+1);group.set(cat,(group.get(cat)||0)+1);features.push({type:'Feature',geometry:{type:'Point',coordinates:[p.lon,p.lat]},properties:{id:p.id,name:p.tags.name||'',category:cat}})}centreData=features;const layers=[];for(const [k,count] of cells){const [i,j]=k.split(',').map(Number),x=center[1]+j*250/(111320*Math.cos(center[0]*Math.PI/180)),y=center[0]+i*250/111320,w=250/(111320*Math.cos(center[0]*Math.PI/180)),h=250/111320;layers.push(L.rectangle([[y,x],[y+h,x+w]],{color:'#fff',weight:1,fillColor:count>=20?'#bb4d39':count>=8?'#e3a24c':'#62a68c',fillOpacity:.65}).bindPopup(`${count} объектов OSM в ячейке ~250×250 м`))}extraLayer=L.layerGroup(layers).addTo(map);$('centreMetrics').innerHTML=metricHtml([[valueFmt(valid),'точек интереса'],[valueFmt(cells.size),'занятых ячеек'],[valueFmt(Math.max(0,...cells.values())),'максимум на ячейку'],[valueFmt(group.size),'категорий']]);$('centreBreakdown').innerHTML=[...group.entries()].sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div><span class="bar" style="width:${Math.round(100*v/Math.max(1,valid))}px"></span>${escapeHtml(k)}: ${v}</div>`).join('');$('centreStatus').textContent='Распределение POI по ~250-метровым ячейкам; это количество зарегистрированных объектов, не оценка посещаемости.'}catch(e){$('centreStatus').textContent='Ошибка: '+e.message}finally{$('runCentre').disabled=false}};
$('centreExport').onclick=()=>{if(!centreData){$('centreStatus').textContent='Сначала выполни расчёт.';return}const rows=[['id','name','category','lat','lon'],...centreData.map(f=>[f.properties.id,f.properties.name,f.properties.category,f.geometry.coordinates[1],f.geometry.coordinates[0]])];download('gdansk-centres-poi.csv','\ufeff'+rows.map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv')};
const cityCenters={Gdansk:[54.3521,18.6464],Copenhagen:[55.6761,12.5683],Oslo:[59.9139,10.7522],Hamburg:[53.5503,10.0007],Rotterdam:[51.9244,4.4777],Aarhus:[56.1629,10.2039],Malaga:[36.7213,-4.4214]};
async function cityPoi(name){const c=cityCenters[name],radius=1000;const q=`[out:json][timeout:65];(node["amenity"](around:${radius},${c[0]},${c[1]});node["shop"](around:${radius},${c[0]},${c[1]});node["tourism"](around:${radius},${c[0]},${c[1]}););out body;`;const data=await fetchOverpass(q),set=new Map();for(const e of data.elements){if(e.type==='node'&&e.tags&&classify(e.tags))set.set(e.id,e)}const groups={};for(const e of set.values()){const cat=poiCategory(e.tags);groups[cat]=(groups[cat]||0)+1}return {name,total:set.size,food:groups['Еда / напитки']||0,shops:groups['Торговля']||0,culture:groups['Культура / туризм']||0,services:groups['Другие услуги']||0}}
$('runCompare').onclick=async()=>{const names=['Gdansk',...[...document.querySelectorAll('#cityChoices input:checked')].map(x=>x.value)];if(names.length<2){$('compareStatus').textContent='Выбери хотя бы один город для сравнения.';return}$('runCompare').disabled=true;compareData=[];$('compareTable').innerHTML='';for(const name of names){$('compareStatus').textContent='Загружаю '+name+' ('+(compareData.length+1)+'/'+names.length+')…';try{compareData.push(await cityPoi(name))}catch(e){compareData.push({name,error:e.message})}renderComparison()}$('compareStatus').textContent='Готово. Сравнение выполнено по точкам OSM в радиусе 1 км. Ошибки запросов указаны отдельно.';$('runCompare').disabled=false};
function renderComparison(){$('compareTable').innerHTML='<table><thead><tr><th>Город</th><th>Всего</th><th>Еда</th><th>Торговля</th><th>Культура</th></tr></thead><tbody>'+compareData.map(x=>x.error?`<tr><td>${escapeHtml(x.name)}</td><td colspan="4" class="muted">Ошибка API: ${escapeHtml(x.error)}</td></tr>`:`<tr><td>${escapeHtml(x.name)}</td><td>${x.total}</td><td>${x.food}</td><td>${x.shops}</td><td>${x.culture}</td></tr>`).join('')+'</tbody></table>'}
$('compareExport').onclick=()=>{if(!compareData.length){$('compareStatus').textContent='Сначала выполни сравнение.';return}const cols=['name','total','food','shops','culture','services','error'];download('cities-poi-benchmark.csv','\ufeff'+[cols.join(','),...compareData.map(x=>cols.map(k=>'"'+String(x[k]??'').replace(/"/g,'""')+'"').join(','))].join('\r\n'),'text/csv')};
